/**
 * Action 03 プロンプトを構築する
 * 
 * @param context - 優先順位付けに必要なコンテキスト情報
 * @returns 生成されたプロンプト文字列
 */
export function buildAction03Prompt(context: PrioritizationContext): string {
  const rulesDescription = formatPriorityRules(context.priorityRules);
  const historicalContext = formatHistoricalIssueData(context.historicalIssueData);
  const issuesForAnalysis = formatExtractedIssues(context.extractedIssues);

  return `# Action 03: 課題の優先順位付け

## 目的
提出済み日報から抽出された課題に対して、重要度と緊急度を評価し、優先順位スコアを自動計算して優先度レベルを付与します。

## 優先度付けルール
${rulesDescription}

## 過去の課題データ（再発リスク評価用）
${historicalContext}

## 分析対象の課題
${issuesForAnalysis}

## 実行手順

1. **重要度スコアの計算**
   - 影響範囲（全社/部門/チーム/個人）
   - 顧客への影響有無
   - システム重要度
   - ビジネスインパクト
   各要因に対して 0-100 のスコアを付与し、重み付け平均を計算

2. **緊急度スコアの計算**
   - 報告時刻からの経過時間
   - 問題の進行速度
   - 対応期限の有無
   - 依存関係の有無
   各要因に対して 0-100 のスコアを付与し、重み付け平均を計算

3. **優先順位スコアの算出**
   - 優先度スコア = (重要度スコア × 0.6) + (緊急度スコア × 0.4)
   - スコア範囲: 0-100

4. **優先度レベルの決定**
   - スコアに基づいて以下のレベルを付与:
     * Critical (85-100): 即座の対応が必要
     * High (70-84): 本日中の対応が必要
     * Medium (50-69): 今週中の対応が必要
     * Low (0-49): 計画的な対応で対応可能

5. **再発リスク評価**
   - 過去データから同一または類似課題の発生履歴を検索
   - 発生頻度と解決時間から再発リスクスコア (0-100) を計算
   - 再発リスクが高い場合は優先度を1段階上げることを検討

6. **エスカレーション判定**
   - 以下の条件に該当する場合はエスカレーション対象に指定:
     * 優先度が Critical の場合
     * 顧客クレームまたは重大インシデントの場合
     * 複数部門にまたがる課題の場合
     * 優先度判定ルールに該当しない新規課題タイプの場合

## 出力形式

各課題に対して以下の情報を含む JSON を生成してください:

\`\`\`json
{
  "prioritizedIssues": [
    {
      "id": "課題ID",
      "title": "課題タイトル",
      "description": "課題説明",
      "category": "課題カテゴリ",
      "reportedBy": "報告者",
      "reportedAt": "報告日時",
      "affectedSystems": ["影響を受けるシステム"],
      "customerImpact": false,
      "internalImpact": true,
      "importanceScore": 75,
      "urgencyScore": 80,
      "priorityScore": 77,
      "priorityLevel": "high",
      "recurrenceRisk": 45,
      "escalationRequired": false,
      "reasoning": "優先度判定の理由を簡潔に説明"
    }
  ],
  "escalationIssues": [
    // エスカレーション対象の課題のみ
  ],
  "prioritySummary": {
    "totalIssues": 10,
    "criticalCount": 1,
    "highCount": 3,
    "mediumCount": 4,
    "lowCount": 2,
    "escalationCount": 1,
    "averagePriorityScore": 62.5
  },
  "timestamp": "2024-01-15T09:30:00Z"
}
\`\`\`

## 注意事項

- 優先度判定は客観的な基準に基づいて実施してください
- 同一課題が複数件報告された場合は、統合判断を行い、より高い優先度を付与してください
- 優先度判定ルールに該当しない新規課題タイプが出現した場合は、エスカレーション対象に指定してください
- 再発リスク評価では、過去データから類似パターンを検索し、リスクスコアを算出してください
- 出力は必ず有効な JSON 形式で、上記スキーマに準拠してください
`;
}

/**
 * 優先度付けルールをフォーマットする
 */
function formatPriorityRules(rules: PriorityRule[]): string {
  if (!rules || rules.length === 0) {
    return "優先度付けルールが定義されていません。デフォルトルールを使用します。";
  }

  return rules
    .map((rule) => {
      const importanceFactorsText = rule.importanceFactors
        .map((f) => `  - ${f.type} (重み: ${f.weight}): ${f.description}`)
        .join("\n");

      const urgencyFactorsText = rule.urgencyFactors
        .map((f) => `  - ${f.type} (重み: ${f.weight}): ${f.description}`)
        .join("\n");

      const thresholdsText = rule.scoreThresholds
        .map(
          (t) =>
            `  - ${t.minScore}-${t.maxScore}: ${t.priorityLevel}${t.escalationRequired ? " (エスカレーション対象)" : ""}`
        )
        .join("\n");

      return `### ルール: ${rule.name}

**重要度評価要因:**
${importanceFactorsText}

**緊急度評価要因:**
${urgencyFactorsText}

**スコア閾値:**
${thresholdsText}`;
    })
    .join("\n\n");
}

/**
 * 過去の課題データをフォーマットする
 */
function formatHistoricalIssueData(issues: HistoricalIssue[]): string {
  if (!issues || issues.length === 0) {
    return "過去の課題データがありません。";
  }

  return issues
    .map(
      (issue) =>
        `- **${issue.title}** (カテゴリ: ${issue.category})
  発生回数: ${issue.occurrenceCount}回
  最終発生: ${issue.lastOccurredAt}
  平均解決時間: ${issue.resolutionTime}時間
  リスクスコア: ${issue.riskScore}/100`
    )
    .join("\n");
}

/**
 * 抽出された課題をフォーマットする
 */
function formatExtractedIssues(issues: ExtractedIssue[]): string {
  if (!issues || issues.length === 0) {
    return "分析対象の課題がありません。";
  }

  return issues
    .map(
      (issue, index) =>
        `${index + 1}. **${issue.title}** (ID: ${issue.id})
   カテゴリ: ${issue.category}
   説明: ${issue.description}
   報告者: ${issue.reportedBy}
   報告日時: ${issue.reportedAt}
   影響システム: ${issue.affectedSystems?.join(", ") || "なし"}
   顧客影響: ${issue.customerImpact ? "あり" : "なし"}
   内部影響: ${issue.internalImpact ? "あり" : "なし"}`
    )
    .join("\n\n");
}
